void input(int &n,int &m,int &q,int &B)  
{
	n=in(),m=in(),q=in();
	long double ln2=0.693,w=64;
	B=n/(6*w*ln2)*(1+sqrt(1+24*w*w*ln2*ln2/q));
	B=max(B,1),B=min(B,n),clear(n,B);

	for(int i=1;i<=m;i++)
	{
		int u=in(),v=in();
		e[v].push_back(u),deg[u]++;  
	}
	for(int i=1;i<=n;i++)a[i]=in(),ida[a[i]]=i;
	for(int i=1;i<=n;i++)b[i]=in(),idb[b[i]]=i;  
}
bitset<N>f[N];
void topo(const int n)  
{
	queue<int>q;
	for(int i=1;i<=n;i++)if(!deg[i])q.push(i);
	while(!q.empty())
	{
		int u=q.front();q.pop();
		for(int v:e[u])
		{
			f[v]|=f[u];  
			if(--deg[v]==0)q.push(v);
		}
	}
}
int n,m,q,B;
void init(bitset<N>(&fa)[M],int (&ida)[N])  
{
	for(int i=0;i<=n/B+1;i++)
		for(int j=max(i*B,1);j<=n;j++)fa[i].set(ida[j]);
}
void modify(bitset<N>(&s)[M],int (&a)[N],const int x,const int y)  
{
	for(int i=0;i<=a[x]/B;i++)s[i].reset(x);
	for(int i=0;i<=a[y]/B;i++)s[i].reset(y);
	for(int i=0;i<=a[x]/B;i++)s[i].set(y);
	for(int i=0;i<=a[y]/B;i++)s[i].set(x);  
}
bitset<N>fa[M],fb[M];
int find(int l,int r,bitset<N>&A)  
{
	int ans=-1;
	while(l<=r)
	{
		int mid=(l+r)>>1;
		if((fb[mid]&A).any())ans=mid,l=mid+1;
		else r=mid-1;
	}
	return ans;
}
int query(const int x,const int l,const int r)  
{
	int bl=l/B,br=r/B;
	bitset<N>A,tmp;
	if(bl<br)
	{
		A=fa[bl+1]^fa[br];  
		for(int i=l;i<(bl+1)*B;i++)A.set(ida[i]);
		for(int i=br*B;i<=r;i++)A.set(ida[i]);  
	}
	else for(int i=l;i<=r;i++)A.set(ida[i]);
	A&=f[x];int p=find(0,n/B+1,A);  
	if(p==-1)return 0;  
	tmp=(fb[p]^fb[p+1])&A;
	for(int i=min((p+1)*B-1,n);i>=p*B;i--)if(tmp.test(idb[i]))return i;  
	return 0;  
}
void work()
{
	input(n,m,q,B),topo(n),init(fa,ida),init(fb,idb);
	while(q--)
