		if(op==2){int x=in(),y=in();modify(fb,b,x,y),swap(idb[b[x]],idb[b[y]]),swap(b[x],b[y]);}
		if(op==3){int x=in(),l=in(),r=in();out(query(x,l,r)),putchar('\n');}
	}
}
