} e[N << 2];
inline void add(int u, int v) {
    e[++cnt].v = v;
    e[cnt].next = h0[u];
    h0[u] = cnt;
    ++in[v];
}
bitset<N> ok, g[N], s[N >> 1];
int a[N], b[N], ti[N];
int op[N], x[N], y[N], z[N], res[N];
int tot;
struct node {
    int x, a, b;
    int tl, tr;
} uu[N << 2];
inline void upd(int x, int t) {
    uu[ti[x]].tr = t;
    uu[ti[x] = ++tot] = (node){x, a[x], b[x], t, 100001};
}
vector<int> vec[N];
inline bool cmp(const node &x, const node &y) {
    return x.b > y.b;
}
void work() {
    int n, m, q;
    fin >> n >> m >> q;
    cnt = 0;
    memset(h0, 0, sizeof(h0));
    for (int i = 1; i <= m; i++) {
        int u, v;
        fin >> u >> v;
        add(u, v);
    }
    for (int i = 1; i <= n; i++)
        fin >> a[i];
    for (int i = 1; i <= n; i++) {
        fin >> b[i];
        uu[ti[i] = i] = (node){i, a[i], b[i], 0, 100001};
        vec[i].clear();
        g[i].reset();
    }
    tot = n;
    ok.reset();
    int num = 0;
    for (int i = 1; i <= q; i++) {
        fin >> op[i];
        if (op[i] < 3) {
            fin >> x[i] >> y[i];
            if (op[i] == 1)
                swap(a[x[i]], a[y[i]]);
            else
                swap(b[x[i]], b[y[i]]);
            upd(x[i], num);
            upd(y[i], num);
        } else {
            fin >> z[i] >> x[i] >> y[i];
            res[++num] = 0;
            ok.set(num);
            g[z[i]].set(num);
            vec[x[i]].push_back(num);
            if (y[i] <= n)
                vec[y[i] + 1].push_back(-num);
        }
    }
    queue<int> qq;
    for (int i = 1; i <= n; i++)
        if (!in[i])
            qq.push(i);
    while (qq.size()) {
        int u = qq.front();
        qq.pop();
        for (int i = h0[u]; i; i = e[i].next) {
            int v = e[i].v;
            g[v] |= g[u];
            --in[v];
            if (!in[v])
                qq.push(v);
        }
    }
    sort(uu + 1, uu + tot + 1, cmp);
    int lim = n >> 1;
    s[0].reset();
    for (int i = 1; i <= lim; i++) {
        s[i] = s[i - 1];
        for (int x : vec[i])
            if (x > 0)
                s[i].set(x);
            else
                s[i].reset(-x);
    }
    for (int i = 1; i <= tot; i++) {
        if (uu[i].a > lim)
            continue;
        bitset<N> tmp = ok & s[uu[i].a] & g[uu[i].x];
        int now = tmp._Find_next(uu[i].tl);
        while (now <= uu[i].tr) {
            ok.reset(now);
            res[now] = max(res[now], uu[i].b);
            now = tmp._Find_next(now);
        }
    }
    for (int i = 1; i <= num; i++)
        ok.set(i);
    s[0] = s[lim];
    for (int i = 1; i <= n - lim; i++) {
        s[i] = s[i - 1];
        for (int x : vec[i + lim])
            if (x > 0)
                s[i].set(x);
            else
                s[i].reset(-x);
    }
    for (int i = 1; i <= tot; i++) {
        if (uu[i].a <= lim)
            continue;
        bitset<N> tmp = ok & s[uu[i].a - lim] & g[uu[i].x];
        int now = tmp._Find_next(uu[i].tl);
        while (now <= uu[i].tr) {
            ok.reset(now);
            res[now] = max(res[now], uu[i].b);
            now = tmp._Find_next(now);
        }
    }
    for (int i = 1; i <= num; i++)
        fout << res[i] << '\n';
}
int main() {
